  gsub(/^[ \t]+|[ \t]+$/,"",line)
  n=split(line,a,/[ \t]+/)
  numre="^[-+]?[0-9]*\\.?[0-9]+$"
  if (n!=4 || a[1]!~/^[0-9]+$/ || a[2]!~numre || a[3]!~numre || a[4]!~numre) {
