Think: Scan temp_workspace/listing.raw for entries named "workspace", run stat on each to keep only confirmed regular files, write those annotated lines to temp_workspace/matches.txt, and produce temp_workspace/status.txt with "found" or "not_found".

Act: bash

```bash
awk '
BEGIN{count=0; matches="temp_workspace/matches.txt"; status="temp_workspace/status.txt"; system("rm -f " matches " " status)}
{
  n = split($0, parts, "/")
  if(parts[n]=="workspace"){
    path = $0
    cmd = "stat -c \"%n||%F||%s||%U||%G||%a||%y\" \"" path "\" 2>/dev/null"
    if((cmd | getline out) > 0){
      close(cmd)
      split(out, f, "\\|\\|")
      if(f[2]=="regular file"){
        print out " CONFIRMED" >> matches
        count++
      }
    } else {
      close(cmd)
    }
  }
}
END{
  if(count>0) print "found" > status
  else print "not_found" > status
}
' temp_workspace/listing.raw
```

